<?php
namespace App\Http\Controllers;
use App\Models\Product; use App\Models\Category; use App\Models\Supplier; use Illuminate\Http\Request;
class ProductController extends Controller {
 public function index(Request $request){ $sort=in_array($request->get('sort'),['name','sku','price','stock','created_at'])?$request->get('sort'):'name'; $direction=$request->get('direction')==='desc'?'desc':'asc'; $products=Product::with(['category','supplier'])->when($request->filled('search'),fn($q)=>$q->where(fn($w)=>$w->where('name','like','%'.$request->search.'%')->orWhere('sku','like','%'.$request->search.'%')))->when($request->filled('category_id'),fn($q)=>$q->where('category_id',$request->category_id))->orderBy($sort,$direction)->paginate(10)->withQueryString(); $categories=Category::orderBy('name')->get(); return view('products.index',compact('products','categories','sort','direction')); }
 public function create(){ $categories=Category::orderBy('name')->get(); $suppliers=Supplier::orderBy('name')->get(); return view('products.create',compact('categories','suppliers')); }
 public function store(Request $r){ $d=$r->validate(['sku'=>'required|string|max:50|unique:products,sku','name'=>'required|string|max:150','category_id'=>'required|exists:categories,id','supplier_id'=>'nullable|exists:suppliers,id','price'=>'required|numeric|min:0','stock'=>'required|integer|min:0']); Product::create($d); return redirect()->route('products.index')->with('success','Produk berhasil ditambahkan.'); }
 public function show(Product $product){$product->load(['category','supplier']);return view('products.show',compact('product'));}
 public function edit(Product $product){$categories=Category::orderBy('name')->get();$suppliers=Supplier::orderBy('name')->get();return view('products.edit',compact('product','categories','suppliers'));}
 public function update(Request $r,Product $product){$d=$r->validate(['sku'=>'required|string|max:50|unique:products,sku,'.$product->id,'name'=>'required|string|max:150','category_id'=>'required|exists:categories,id','supplier_id'=>'nullable|exists:suppliers,id','price'=>'required|numeric|min:0','stock'=>'required|integer|min:0']);$product->update($d);return redirect()->route('products.index')->with('success','Produk berhasil diperbarui.');}
 public function destroy(Product $product){if($product->stockMovements()->exists())return back()->withErrors(['product'=>'Produk memiliki riwayat transaksi stok dan tidak dapat dihapus.']);$product->delete();return redirect()->route('products.index')->with('success','Produk berhasil dihapus.');}
}
